import type { DomainMessages } from './types'

/**
 * 后端错误与状态 tag。
 *
 * 这些是后端**唯一**会返回给前端做展示的文案：后端只回 tag
 * （例如 `error.diyLevel.notRunning`），前端在这里翻译。
 *
 * 命名约定：`<对象>.<失败动作>`，不要写技术细节（"HTTP 500"）
 * 当 tag —— 那些应该落日志，用户看到的是可执行的建议。
 *
 * 参数用 `{}` 占位，由调用方传入。后端回参数时以 JSON 附带，
 * 前端把参数原样传给 `t()`。
 */
